import {enrichCity} from './urban-detail.js';
import {cityScenery} from './city-scenery.js';
import * as T from 'three';
import {box,cylinder,sign,mat,tree,person,vehicle} from './models.js';
import {createGarage} from './garage.js';
import {block,roads,hospitalPoint} from './roads.js';
export function neighborhood(scene){const root=new T.Group();scene.add(root);box(root,930,1,610,'#829375',60,-.6,0);const lamps=[],citizens=[],hydrants=[],traffic=[],buildings=[];
for(const r of roads){const dx=r.b[0]-r.a[0],dz=r.b[1]-r.a[1],len=Math.hypot(dx,dz),x=(r.a[0]+r.b[0])/2,z=(r.a[1]+r.b[1])/2,yaw=Math.atan2(dx,dz);for(const [w,y,color]of (r.trail?[[9,.05,'#8c896a'],[6,.16,'#ae9a74']]:[[13,.04,'#b2b6ac'],[9,.16,'#555f62']])){const m=box(root,w,.13,len+.2,color,x,y,z);m.rotation.y=yaw;}if(len>25&&!r.trail){for(let d=5;d<len;d+=9){const m=box(root,.12,.025,3,'#e5dfc3',r.a[0]+dx*d/len,.25,r.a[1]+dz*d/len);m.rotation.y=yaw;}const tx=x+dz/len*6,tz=z-dx/len*6;cylinder(root,.09,.12,6,'#5b6c6d',tx,3,tz,6);lamps.push(box(root,.7,.15,.4,new T.MeshStandardMaterial({color:'#eee6c6',emissive:'#ffe5b0',emissiveIntensity:.1}),tx,6,tz));const h=new T.Group();h.position.set(x-dz/len*6,0,z+dx/len*6);root.add(h);cylinder(h,.28,.32,1.05,'#be3d2d',0,.6,0);box(h,.85,.24,.25,'#dc5541',0,.8,0);hydrants.push(h);if(!r.name.includes('(simulation)')){const label=sign(root,r.name,Math.min(20,len*.7),1.1,x+dz/len*5.6,.3,z-dx/len*5.6,'#a9b1a6','#3c5154');label.rotation.x=-Math.PI/2;label.rotation.z=yaw-Math.PI/2;}}}
for(const [i,b]of block.buildings.entries()){const points=b.points,shape=new T.Shape();points.forEach(([x,z],j)=>j?shape.lineTo(x,-z):shape.moveTo(x,-z));const height=Math.min(27,Math.max(3,b.levels*3));const geo=new T.ExtrudeGeometry(shape,{depth:height,bevelEnabled:false});geo.rotateX(-Math.PI/2);const m=new T.Mesh(geo,mat(['#d7cdb7','#c4bcab','#d2bca5'][i%3]));m.castShadow=true;m.receiveShadow=true;root.add(m);buildings.push(m);const roof=new T.Mesh(new T.ShapeGeometry(shape),mat('#657174'));roof.rotation.x=-Math.PI/2;roof.position.y=height+.05;root.add(roof);for(let j=0;j<points.length-1;j++){const a=points[j],c=points[j+1],len=Math.hypot(c[0]-a[0],c[1]-a[1]);if(len<3)continue;const yaw=Math.atan2(c[0]-a[0],c[1]-a[1]);for(let d=2;d<len-1;d+=3.5)for(let y=1.9;y<height-.5;y+=3){const w=box(root,.12,1.3,1.25,'#314b55',a[0]+(c[0]-a[0])*d/len,y,a[1]+(c[1]-a[1])*d/len);w.rotation.y=yaw;}}}
const beach=cityScenery(root);enrichCity(root,block,roads);const {station,roofs}=createGarage(root);roofs.forEach(r=>r.visible=false);// Marked apron and separated one-way approach / departure lanes at the CH.
box(root,13,.09,64,'#778583',372,.12,-122);
for(let i=0;i<4;i++){const z=-141+i*10;for(const x of[373.5,376.5])box(root,.08,.02,7.5,'#dcdcc0',x,.18,z);}
for(const z of[-143,-125,-106]){box(root,.12,.02,2,'#dedcc4',367,.18,z);box(root,1,.02,.13,'#dedcc4',367,.18,z+.8);}
const hospital=new T.Group();hospital.position.set(390,0,-120);root.add(hospital);box(hospital,21,8,35,'#deded1',0,4,0);box(hospital,22,.4,36,'#768e92',0,8.2,0);for(let z=-12;z<=12;z+=4)box(hospital,.12,2,2.5,'#365964',-10.6,4,z);sign(hospital,'CH • URGENCES',16,1.6,0,6,17.6,'#397682');box(hospital,8,.2,9,'#7b8d8d',-13,4.4,0);for(let z of[-5,5])box(hospital,.15,2.6,2,'#92b8ba',-10.6,1.4,z);sign(root,'DÉPOSE VSAV',12,1,-1+hospitalPoint[0],.35,hospitalPoint[1],'#477a84').rotation.x=-Math.PI/2;
const usable=roads.filter(r=>!r.trail&&!r.name.includes('(simulation)')&&Math.hypot(r.a[0]-r.b[0],r.a[1]-r.b[1])>15);for(let i=0;i<22;i++){const r=usable[i%usable.length],p=person(root,0,0,['#aa705a','#516c85','#887f54'][i%3]);citizens.push({model:p,road:r,phase:i/22});}for(let i=0;i<10;i++){const r=usable[(i*3)%usable.length],car=vehicle(root,'VLCG',['#7d9391','#c5b99b','#55737e','#9d6656'][i%4]);car.userData.beacons.forEach(b=>b.visible=false);car.scale.setScalar(.85);const dx=r.b[0]-r.a[0],dz=r.b[1]-r.a[1],len=Math.hypot(dx,dz);car.position.set(r.a[0]+dx*i/10-dz/len*(r.express?5:2),0,r.a[1]+dz*i/10+dx/len*(r.express?5:2));car.rotation.y=Math.atan2(dx,dz);traffic.push({model:car,road:r,progress:i/10});}for(let i=0;i<16;i++)tree(root,-20+(i%4)*7,-95+Math.floor(i/4)*10,1,i%4);
const fireBuilding=new T.Group();scene.add(fireBuilding);fireBuilding.userData={width:8,depth:8,height:4};return{root,fireBuilding,buildings,lamps,citizens,traffic,station,roofs,hydrants,block,hospitalPoint,beach};}
